  ["highground.coachbounties.inspect_a_reward_before_tracking_it.d290ec"] = "Belohnung vor dem Verfolgen prüfen",
  ["highground.coachbounties.this_wanted_card_offers_a_reward_for.b6fd13"] = "Diese Steckbriefkarte bietet eine Belohnung für {value2}. Öffnen Sie sie, um die vollständigen Bedingungen zu lesen.",
  ["highground.coachbounties.click_view_bounty_or_next.dc340a"] = "Klicken Sie auf Kopfgeld anzeigen oder Weiter.",
  ["highground.coachbounties.check_what_earns_the_reward.391d20"] = "Prüfen, was die Belohnung einbringt",
  ["highground.coachbounties.check_the_target_reward_and_expiry_read.94c5fa"] = "Prüfen Sie Ziel, Belohnung und Ablauf. Lesen Sie alle benutzerdefinierten Bedingungen darunter; lange Steckbriefe lassen sich scrollen. Kehren Sie zur Karte zurück, um die Verfolgung zu starten. Es ist kein Beitrag erforderlich.",
  ["highground.coachbounties.click_back_to_preview_or_next.d9e682"] = "Klicken Sie auf Zurück zur Vorschau oder Weiter.",
  ["highground.coachbounties.start_tracking_this_target.50a0d0"] = "Verfolgung dieses Ziels starten",
  ["highground.coachbounties.choose_start_tracking_the_card_changes_to.b9aa0d"] = "Wählen Sie Verfolgung starten. Die Karte wechselt zu VERFOLGT und erscheint unter Meine Kopfgelder. Verfolgung beenden schaltet die Warnungen aus; Ihre Belohnungen und Berichte bleiben erhalten. Verfolgen sagt kein Gold zu.",
  ["highground.coachbounties.already_tracking_this_target_next_continues_to.eb8954"] = "Dieses Ziel wird bereits verfolgt. Weiter führt zu seiner Beispielsichtung.",
  ["highground.coachbounties.click_start_tracking_next_activates_the_highlighted.5f13d4"] = "Klicken Sie auf Verfolgung starten. Weiter aktiviert das markierte Steuerelement.",
  ["highground.coachbounties.sample_event_your_target_is_nearby.f5e819"] = "Beispielereignis: Ihr Ziel ist in der Nähe",
  ["highground.coachbounties.a_sighting_detects_value2_the_same_target.a41058"] = "Eine Sichtung erkennt {value2}, das gleiche Ziel, das Sie zur Verfolgung ausgewählt haben. Schließen Sie diese Warnung, um mit einem Beispiel-Kill fortzufahren, oder prüfen Sie den Steckbrief erneut.",
  ["highground.coachbounties.close_the_wanted_alert_or_next_to.724954"] = "Schließen Sie die Steckbriefwarnung oder klicken Sie auf Weiter, um die Schließen-Schaltfläche zu aktivieren.",
  ["highground.coachbounties.sample_event_the_target_is_killed.ca18c1"] = "Beispielereignis: Das Ziel wird getötet",
  ["highground.coachbounties.the_addon_creates_the_report_automatically_a.1fa40f"] = "Das Addon erstellt den Bericht automatisch. Ein lesbarer Todesstoß wird bestätigt; Ehre kann auch für Assists vergeben werden. Das Screenshot-Häkchen bedeutet nur, dass das Bild gespeichert wurde. Öffnen Sie den Bericht, um die Prüfung zu verfolgen.",
  ["highground.coachbounties.click_view_sample_report_copying_proof_is.ecb999"] = "Klicken Sie auf Beispielbericht anzeigen. Das Kopieren des Nachweises ist optional; es wird kein echter Screenshot oder Bericht gesendet.",
  ["highground.coachbounties.bounty_ignored.3d5adf"] = "Kopfgeld ignoriert",
  ["highground.coachbounties.follow_your_own_claim.e2d148"] = "Eigenen Anspruch verfolgen",
  ["highground.coachbounties.this_target_was_not_added_to_your.871630"] = "Dieses Ziel wurde nicht zu Ihren verfolgten Kopfgeldern hinzugefügt. Starten Sie den Jagdablauf erneut, wann immer Sie einen Anspruch ausprobieren möchten.",
  ["highground.coachbounties.your_report_is_saved_its_next_step.c8431b"] = "Ihr Bericht ist gespeichert. Sein nächster Schritt erklärt Zustellung, Prüfung oder Zahlung. Der Aussteller prüft die Belohnung und zahlt im Spiel. Verwenden Sie Belohnung beanspruchen oder Einen verpassten Kill melden nur, wenn die Erkennung einen Tod verpasst hat.",
  ["highground.coachbounties.done_returns_to_the_two_bounty_paths.aa70f3"] = "Fertig kehrt zu den beiden Kopfgeld-Abläufen zurück. Es wurden keine echten Berichte, Screenshots oder Nachrichten gesendet.",
  ["highground.coachbountysamples.nightshade_vale.0d981c"] = "Nightshade Vale-",
  ["highground.coachbountysamples.posted_by_value2.435384"] = "Ausgesetzt von {value2}",
  ["highground.coachbountysamples.report_declined.d051d9"] = "Bericht abgelehnt",
  ["highground.coachbountysamples.1_awaiting_review.3b8407"] = "1 wartet auf Prüfung",
  ["highground.coachbountysamples.no_sample_kill_yet_continue_the_hunt.35271c"] = "Noch kein Beispiel-Kill. Setzen Sie die Jagd fort, bevor Sie ihn melden.",
  ["highground.coachbountysamples.this_sample_kill_is_already_submitted_view.e01249"] = "Dieser Beispiel-Kill ist bereits eingereicht. Klicken Sie auf Ansprüche anzeigen, um der Bewertung zu folgen.",
  ["highground.coachbountysamples.sample_kill_submitted_awaiting_the_poster_s.5a1179"] = "Beispiel-Kill eingereicht · Wartet auf die Prüfung durch den Aussteller. Öffnen Sie Ansprüche anzeigen, um Ihren Bericht zu verfolgen.",
  ["highground.coachbountysamples.claim_reward.c3e030"] = "Belohnung beanspruchen",
  ["highground.coachbountysamples.fallback_for_a_missed_detection_detected_kills.2d8911"] = "Ersatz für eine verpasste Erkennung. Erkannte Kills erstellen automatisch Berichte.",
  ["highground.coachbountysamples.see_this_bounty_s_sample_reports_and.edc6d8"] = "Sehen Sie sich die Beispielberichte und den Zahlungsstatus dieses Kopfgelds an.",
