  ["highground.coachbountysamples.import_bounty.00e6b6"] = "Kopfgeld importieren",
  ["highground.coachbountysamples.view_report.7398c9"] = "Bericht anzeigen",
  ["highground.coachbountysamples.review_report.29a1c5"] = "Bericht prüfen",
  ["highground.coachbountysamples.record_payment.86e563"] = "Zahlung erfassen",
  ["highground.coachbountysamples.edit_reward.0854ae"] = "Belohnung bearbeiten",
  ["highground.coachbountysamples.start_tracking.9d94fe"] = "Verfolgung starten",
  ["highground.coachexamples.practice.9d8822"] = "ÜBUNG",
  ["highground.coachexamples.sample_data_try_every_control.1d071d"] = "Beispieldaten · Jede Steuerung ausprobieren",
  ["highground.coachexamples.sample_data_only_enable_in_game_saves.c60890"] = "Beispieldaten. Nur Im Spiel aktivieren speichert eine echte Einstellung.",
  ["highground.coachexamples.use_replay_to_bring_this_control_back.83c8a3"] = "Verwenden Sie Wiederholen, um diese Steuerung wieder anzuzeigen.",
  ["highground.coachmap.a_teammate.aa3d91"] = "ein Teamkollege",
  ["highground.coachmap.silverwing_hold.e68140"] = "Silberschwingenfeste",
  ["highground.coachmap.enemies_on_your_world_map.7062f3"] = "Feinde auf der Weltkarte",
  ["highground.coachmap.this_is_wow_s_world_map_with.e5b392"] = "Dies ist die Weltkarte von WoW mit fünf Beispielfeinden in der Kriegshymnenschlucht. In einem Match erscheinen dieselben Pins auch auf der Schlachtfeldkarte (Umschalt+M). Nur beobachtete Feinde erhalten eine Position.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.da444f"] = "Die Kriegshymnenschlucht ist in diesem Client nicht verfügbar. Dies ist Ihre normale Weltkarte. Kehren Sie zu Anleitungen zurück, um eine andere Funktion auszuprobieren.",
  ["highground.coachmap.start_with_a_fresh_sighting.d7f307"] = "Mit einer neuen Sichtung beginnen",
  ["highground.coachmap.this_bright_rogue_pin_is_a_fresh.bbd705"] = "Dieser helle Schurken-Pin ist eine frische Sichtung. Bewegen Sie die Maus darüber, um zu lesen, wer gesehen wurde und wer ihn beobachtet hat.",
  ["highground.coachmap.hover_the_highlighted_enemy_then_choose_next.7c672d"] = "Bewegen Sie die Maus über den markierten Feind und wählen Sie dann Weiter.",
  ["highground.coachmap.spot_the_suggested_target.2d4580"] = "Das vorgeschlagene Ziel erkennen",
  ["highground.coachmap.the_outer_ring_marks_the_suggested_target.9f5fc2"] = "Der äußere Ring markiert das vorgeschlagene Ziel, wenn eines verfügbar ist. Das Klassensymbol zeigt an, welche Art von Feind beobachtet wurde.",
  ["highground.coachmap.older_sightings_fade.039a3d"] = "Ältere Sichtungen verblassen",
  ["highground.coachmap.this_faded_mage_was_last_seen_36.2fe437"] = "Dieser verblasste Magier wurde zuletzt vor 36 Sekunden gesehen. Die Zeit ist das Alter der Sichtung. Er könnte sich inzwischen bewegt haben; dies ist keine Live-Position.",
  ["highground.coachmap.a_location_can_be_approximate.08cdfb"] = "Ein Standort kann ungefähr sein",
  ["highground.coachmap.a_faint_circle_marks_roughly_where_an.47c0a0"] = "Ein blasser Kreis markiert ungefähr, wo ein Gegner zuletzt gesehen wurde, wenn der genaue Ort unbekannt ist, etwa ein bekanntes Gebiet. Fahren Sie darüber, um zu sehen, wer wann gesehen wurde. Die Beobachtung eines Teammitglieds kann ihn eingrenzen, ohne ungesehene Gegner preiszugeben.",
  ["highground.coachmap.fights_are_circled_where_they_happen.5e393b"] = "Kämpfe werden dort eingekreist, wo sie stattfinden",
  ["highground.coachmap.in_a_fight_the_circle_sits_on.14392f"] = "In einem Kampf liegt der Kreis stattdessen auf dir: Das Spiel zeichnet ihn an deiner tatsächlichen Position, auch wo die Karte nur das Gebiet nennt. Der Kampf eines Teammitglieds kreist dieses Teammitglied ein. Er verblasst etwa 10 Sekunden nach der letzten Sichtung und erscheint nur in echten Schlachtfeldern.",
  ["highground.coachmap.use_the_whole_picture.b9e5f8"] = "Verwenden Sie das ganze Bild",
  ["highground.coachmap.compare_fresh_pins_older_sightings_and_the.a2fa1f"] = "Vergleichen Sie frische Pins, ältere Sichtungen und das Ziel, bevor Sie eine Route auswählen. Diese Beispielsichtungen bleiben außerhalb von Live-Tracking und Gruppenfreigabe. Fertig stellt die vorherige Karte wieder her.",
  ["highground.coachmap.warsong_gulch_is_unavailable_in_this_client.ccb80d"] = "Kriegshymnenschlucht ist in diesem Client nicht verfügbar. Verwenden Sie Anleitungen, um zurückzukehren.",
  ["highground.coachmap.use_replay_to_reopen_warsong_gulch_on.5dd141"] = "Verwenden Sie Wiederholen, um die Kriegshymnenschlucht erneut auf der Weltkarte zu öffnen.",
  ["highground.coachpreferences.changes_here_save_immediately.a4d86e"] = "Änderungen hier werden sofort gespeichert.",
  ["highground.coachpreferences.open_this_addon_s_appearance.f257e1"] = "Darstellung dieses Addons öffnen",
  ["highground.coachpreferences.open_shared_appearance.31a605"] = "Gemeinsame Darstellung öffnen",
  ["highground.coachpreferences.click_appearance_under_battlegrounds_to_adjust_enemy.54bf82"] = "Klicken Sie unter Schlachtfelder auf Darstellung, um feindliche Zeilen und Zielmarkierungen anzupassen.",
  ["highground.coachpreferences.shared_appearance_controls_the_theme_fonts_and.47799d"] = "Gemeinsame Darstellung steuert Design, Schriftarten und Barrierefreiheit für jedes aktivierte Addon.",
  ["highground.coachpreferences.click_appearance_under_battlegrounds.189abb"] = "Klicken Sie unter Schlachtfelder auf Darstellung.",
  ["highground.coachpreferences.click_shared_appearance.962763"] = "Klicken Sie auf Gemeinsame Darstellung.",
  ["highground.coachpreferences.choose_a_shared_theme.8b4434"] = "Ein gemeinsames Design auswählen",
  ["highground.coachpreferences.theme_and_accessibility_apply_to_every_addon.aba586"] = "Design und Barrierefreiheit gelten für jedes Addon. Einzelne Panel-Steuerelemente bleiben im eigenen Bereich des Addons.",
  ["highground.coachpreferences.fine_tune_this_addon_s_panels.60828e"] = "Feinabstimmung der Panels dieses Addons",
  ["highground.coachpreferences.fine_tune_shared_styling.b1faf5"] = "Feinabstimmung des gemeinsamen Stylings",
  ["highground.coachpreferences.these_dimensions_and_row_details_belong_to.538aec"] = "Diese Abmessungen und Zeilendetails gehören zu Schlachtfelder. Arena und Nearby haben eigene Darstellungsseiten.",
  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "Texturen, Farben und Rahmen der Balken werden gemeinsam genutzt. Passen Sie die Größe jedes Panels auf der Darstellungsseite seines eigenen Addons an.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "Einstellungen liegen bei ihrem Addon",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "Verwenden Sie die Seiten Einstellungen, Darstellung, Befehle sowie Vorschauen und Anleitung eines Addons. Schlachtfeld-Panels verwenden /hg bg test. Führen Sie /hg test oder /hg test stop unter Hilfe und Befehle aus, um alle Vorschauen umzuschalten oder zu beenden. Übersicht und Aktivierung legt fest, ob das Addon nach dem Neuladen läuft. Gemeinsame Voreinstellungen wirken sich auf alle Addons aus.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "Behalten Sie die gewünschten Panels",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "Gemeinsame Einstellungen auswählen",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "Angehakt bedeutet aktiviert. Alle verfügbaren Funktionsschalter werden hier angezeigt; scrollen Sie, um den Rest zu sehen.",
  ["highground.coachpreferences.checked_means_enabled_this_switch_shows_the.de650b"] = "Angehakt bedeutet aktiviert. Dieser Schalter zeigt den Highground-Minimap-Button an.",
  ["highground.coachpreferences.choose_the_warnings_you_want.2794f4"] = "Wählen Sie die gewünschten Warnungen aus",
  ["highground.coachpreferences.this_changes_your_real_alert_preference.ecd3f5"] = "Dies ändert Ihre tatsächliche Benachrichtigungseinstellung.",
  ["highground.coachpreferences.go_straight_to_an_addon_s_alerts.46dd58"] = "Gehen Sie direkt zu den Benachrichtigungen eines Addons",
  ["highground.coachpreferences.the_battlegrounds_nearby_and_bounties_links_open.676c0b"] = "Die Links Schlachtfelder, Nearby und Kopfgelder öffnen direkt ihre Text- und Toneinstellungen. Deaktivierte Addons werden verfügbar, nachdem Sie sie unter Addons aktiviert und neu geladen haben.",
  ["highground.coachpreferences.click_battlegrounds_or_next_to_open_its.68ede3"] = "Klicken Sie auf Schlachtfelder oder Weiter, um die Benachrichtigungssteuerung zu öffnen.",
  ["highground.coachpreferences.enemy_stealth_stays_available_here_even_when.63bf57"] = "„Gegnerische Verstohlenheit“ bleibt hier verfügbar, auch wenn ein Addon deaktiviert ist.",
  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "Wählen Sie Text, Ton oder beides",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground ist der einzige Download, den Sie benötigen",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Addons vereint die Addon-Schalter, Einstellungsverknüpfungen und Anleitungen. Entfernen Sie alle separaten eigenständigen Downloads. Behalten Sie jeden Modulordner und beide erforderlichen Daten-Addons. Das Deaktivieren eines Daten-Addons verhindert, dass Highground geladen wird.",
  ["highground.coachpreferences.a_disabled_module_does_not_activate_a.e4cf84"] = "Ein deaktiviertes Modul aktiviert keine eigenständige Kopie. Nichts wird durch diese Anleitung entfernt.",
  ["highground.coachpreferences.choose_which_addons_run.892aae"] = "Wählen Sie, welche Addons ausgeführt werden sollen",
  ["highground.coachpreferences.enable_addon_is_the_same_per_character.e05474"] = "Addon aktivieren ist derselbe charakterbezogene Schalter wie in der AddOn-Liste von WoW. Alle sechs Sub-Addons sind im Highground-Download enthalten.",
  ["highground.coachpreferences.these_are_real_switches_you_can_continue.862243"] = "Das sind echte Schalter. Sie können weitermachen, ohne etwas zu ändern.",
  ["highground.coachpreferences.visit_settings_or_replay_a_guide.e879b6"] = "Einstellungen aufrufen oder eine Anleitung wiedergeben",
  ["highground.coachpreferences.visit_opens_this_addon_s_overview_and.64e863"] = "Besuchen öffnet die Übersicht und Einstellungen dieses Addons. Starten, Fortsetzen oder Wiederholen öffnet seine Anleitung und behält die gespeicherte Stelle bei.",
  ["highground.coachpreferences.visit_leaves_this_walkthrough_next_continues_without.da36c5"] = "Besuchen verlässt diese Anleitung. Weiter fährt ohne Besuch fort.",
  ["highground.coachpreferences.recognize_subaddons_in_the_sidebar.8ccd1c"] = "Sub-Add-ons in der Seitenleiste erkennen",
  ["highground.coachpreferences.each_subaddon_has_a_small_crest_and.3b587c"] = "Jedes Sub-Addon hat ein kleines Wappen und einen Akzentstreifen. Erweitern Sie seinen Abschnitt für Übersicht und Aktivierung, Einstellungen, Darstellung (sofern verfügbar), Befehle sowie Vorschauen und Anleitung.",
  ["highground.coachpreferences.shared_preferences_saved_setups_and_help_apply.3e1969"] = "Gemeinsame Voreinstellungen, Gespeicherte Konfigurationen und Hilfe gelten über ein einzelnes Addon hinaus.",
  ["highground.coachpreferences.keep_your_settings_when_disabling_an_addon.518274"] = "Behalten Sie Ihre Einstellungen beim Deaktivieren eines Addons bei",
  ["highground.coachpreferences.changing_a_switch_takes_effect_after_reload.145c67"] = "Das Ändern eines Schalters wird nach dem Neuladen wirksam. Gespeicherte Panel-Einstellungen und Datensätze bleiben erhalten. Panel anzeigen auf den Karten von Nearby und Arena ändert nur die Panel-Einstellung. Wird Addon aktivieren vor dem Neuladen zurückgestellt, wird diese Änderung aufgehoben.",
  ["highground.coachpreferences.profiles_do_not_enable_or_disable_addons.a7920d"] = "Profile aktivieren oder deaktivieren keine Add-ons.",
  ["highground.coachpreferences.reload_when_you_are_ready.225a57"] = "Neu laden, wenn Sie bereit sind",
  ["highground.coachpreferences.after_changing_a_switch_reload_to_apply.8a851b"] = "Nachdem Sie einen Schalter geändert haben, erscheint unter Addons Zum Anwenden neu laden. Laden Sie außerhalb des Kampfes neu, um aktivierte Module zu starten und deaktivierte zu stoppen. Die Anleitung lädt nie automatisch neu.",
  ["highground.coachpreferences.next_continues_without_reloading.acc474"] = "Weiter fährt ohne Neuladen fort.",
  ["highground.coachpreferences.find_commands_and_their_controls.a1ca25"] = "Suchen von Befehlen und deren Steuerelementen",
  ["highground.coachpreferences.each_addon_has_a_commands_page_help.cc07e2"] = "Jedes Addon hat eine Befehlsseite; Hilfe und Befehle kombiniert sie. Jeder Befehl verwendet eine Zeile. Bewegen Sie den Mauszeiger für die vollständige Syntax und Aliase. Die Schaltfläche öffnet Einstellungen, führt die Aktion aus oder öffnet beschriftete Felder für ihre Werte.",
  ["highground.coachpreferences.browsing_is_safe_action_buttons_can_change.33ba22"] = "Browsen ist sicher. Aktionsschaltflächen können reale Einstellungen ändern; diese Anleitung klickt sie nicht an.",
  ["highground.coachpreferences.discover_channel_members.5df463"] = "Channel-Mitglieder entdecken",
  ["highground.coachpreferences.your_own_character_counts_immediately_a_complete.2a1246"] = "Ihr eigener Charakter zählt sofort. Eine vollständige Kanalmitgliederliste fügt andere Mitglieder hinzu, bevor deren Addon-Ankündigungen eintreffen. „Mitglieder aktualisieren“ zeigt eine Ladeanzeige und bleibt während des Wartens deaktiviert. Klicken Sie auf „Ausprobieren“, um einen Beispiel-Austritt zu sehen.",
  ["highground.coachpreferences.this_sample_does_not_request_a_live.d4e060"] = "Dieses Beispiel fordert keine Live-Mitgliederliste an und sendet keine Nachrichten.",
  ["highground.coachpreferences.membership_and_version_reports_are_different.84c36a"] = "Mitgliedschafts- und Versionsberichte unterscheiden sich",
  ["highground.coachpreferences.a_channel_member_may_not_have_a.590af5"] = "Ein Channel-Mitglied hat möglicherweise kein antwortendes Addon. Mitglieder ohne Ankündigung werden separat gezählt. Versionen stammen nur aus empfangenen Ankündigungen; prüfen Sie Update-Hinweise in Ihrem Addon-Manager.",
  ["highground.coachpreferences.keep_useful_counts_when_a_list_is.120802"] = "Nützliche Zählungen beibehalten, wenn eine Liste nicht verfügbar ist",
  ["highground.coachpreferences.an_incomplete_or_unavailable_member_list_keeps.d5bf62"] = "Eine unvollständige oder nicht verfügbare Mitgliederliste behält die letzte vollständige Liste für kurze Zeit bei und fällt dann auf die letzten Ankündigungen zurück. Zählungen können Charaktere enthalten, die seitdem gegangen sind. Die Gruppen- und Gildenentdeckung verwendet weiterhin Ankündigungen.",
  ["highground.coachpreferences.close_the_guide_to_return_to_live.65ab77"] = "Schließen Sie die Anleitung, um zu den Live-Zählungen zurückzukehren. Die Ermittlungseinstellungen sind nur in diesem Beispiel deaktiviert.",
  ["highground.coachrecords.joined_warsong_gulch.06bcbe"] = "Kriegshymnenschlucht beigetreten",
  ["highground.coachrecords.your_team_captured_the_flag.27a3c4"] = "Ihr Team hat die Flagge erobert",
  ["highground.coachrecords.victory.e71f15"] = "Sieg",
  ["highground.coachrecords.left_early.3e26fd"] = "Früh verlassen",
  ["highground.coachrecords.joined_arathi_basin.aa8cb9"] = "Arathibecken beigetreten",
  ["highground.coachrecords.left_before_the_result_was_observed.305ce8"] = "Verlassen, bevor das Ergebnis beobachtet wurde",
  ["highground.coachrecords.sample_records_summary.ea5f24"] = "Beispieleinträge · {summary}",
  ["highground.coachrecords.find_a_previous_match.8646a0"] = "Vorheriges Match suchen",
  ["highground.coachrecords.search_by_map_result_or_character_these.9f622d"] = "Suchen Sie nach Karte, Ergebnis oder Charakter. Diese Beispieleinträge verwenden dasselbe Verlaufsfenster wie Ihre eigenen Matches.",
  ["highground.coachrecords.choose_a_match_to_inspect.91330e"] = "Wählen Sie ein Match zum Ansehen",
  ["highground.coachrecords.select_warsong_gulch_or_arathi_basin_left.1fabad"] = "Wählen Sie Kriegshymnenschlucht oder Arathibecken. Früh verlassen bedeutet, dass das Ergebnis nicht beobachtet wurde; fehlende Statistiken bleiben leer.",
