  ["highground.coachtargeting.target_markers.c4b1df"] = "ZIELMARKIERUNGEN",
  ["highground.coachtargeting.lunara_is_suggested_vexa_is_your_current.48ae7f"] = "Lunara wird vorgeschlagen. Vexa ist Ihr aktuelles Ziel.",
  ["highground.coachtargeting.show_sample_enemy_nameplates.7e4f83"] = "Beispiel-Namensschilder für Feinde anzeigen",
  ["highground.coachtargeting.use_target_recommendations_in_the_sample.98610c"] = "Zielempfehlungen im Beispiel verwenden",
  ["highground.coachtargeting.suggested_lunara_your_target_vexa.ca3f9d"] = "Vorgeschlagen: Lunara · Ihr Ziel: Vexa",
  ["highground.coachtargeting.recommendations_off_the_sniper_marker_follows_your.3d1a5e"] = "Empfehlungen aus: Die Scharfschützenmarkierung folgt Ihrem Ziel, Vexa.",
  ["highground.coachtargeting.the_sniper_marker_shows_the_suggestion.d28836"] = "Die Scharfschützenmarkierung zeigt den Vorschlag",
  ["highground.coachtargeting.it_points_to_lunara_your_selected_target.7e9f71"] = "Sie zeigt auf Lunara. Ihr ausgewähltes Ziel ist weiterhin Vexa; Sie entscheiden, ob Sie wechseln. Dieses Beispiel verwendet Ihren gespeicherten Stil, Ihre Farben und Ihre Totenkopf-Wahl. Schlachtfelder → Darstellung → Scharfschützenmarkierung bietet das neue Visier oder „Altes Fadenkreuz“, separate Farben, Platzierung und Größe. Die Kopfplatzierung ist ungefähr.",
  ["highground.coachtargeting.try_hg_sniper_test_on_a_target.72718a"] = "Probieren Sie /hg sniper test bei einem Ziel mit sichtbarem Namensschild aus, dann /hg go für die Ansicht des Kill-Fensters. Niedrigere Gesundheit beschleunigt das Pulsieren; Reduzierte Bewegung hält es ruhig. Wiederholen Sie /hg sniper test, um zu stoppen.",
  ["highground.coachtargeting.enable_sniper_marker_in_game.53767b"] = "Scharfschützenmarkierung im Spiel aktivieren",
  ["highground.coachtargeting.this_cross_marks_a_healer.3e70f2"] = "Dieses Kreuz markiert einen Heiler",
  ["highground.coachtargeting.the_red_cross_identifies_a_known_enemy.f8294e"] = "Das rote Kreuz kennzeichnet einen bekannten gegnerischen Heiler. Verbündete Heiler erhalten ein grünes Kreuz.",
  ["highground.coachtargeting.enable_healer_marks_in_game.8c2663"] = "Heilermarkierungen im Spiel aktivieren",
  ["highground.coachtargeting.keep_enemy_nameplates_visible.183b52"] = "Feindliche Namensschilder sichtbar halten",
  ["highground.coachtargeting.turn_sample_nameplates_off_then_on_in.61ded4"] = "Schalten Sie Beispiel-Namensschilder aus und dann ein. Im Spiel benötigen diese Marker auch sichtbare Namensschilder.",
  ["highground.coachtargeting.in_game_battlegrounds_settings_nameplates_sets_their.9d5201"] = "Im Spiel legen Sie unter Schlachtfelder-Einstellungen → Namensschilder ihre Reichweite fest und zeigen sie ohne Anvisieren an. /hg nameplates macht dasselbe.",
  ["highground.coachtargeting.try_following_your_own_target.acd537"] = "Versuchen Sie, Ihrem eigenen Ziel zu folgen",
  ["highground.coachtargeting.turn_sample_recommendations_off_the_sniper_marker.02c850"] = "Deaktivieren Sie die Beispielempfehlungen. Die Scharfschützenmarkierung wechselt zu Vexa, Ihrem aktuellen Ziel.",
  ["highground.coachtargeting.your_battleground_enemy_list.62d16e"] = "Ihre Feindliste auf dem Schlachtfeld",
  ["highground.coachtargeting.this_is_your_actual_enemy_panel_with.9e06eb"] = "Dies ist Ihr tatsächliches Feindpanel mit Beispielgegnern. Bewegen Sie den Mauszeiger über eine Zeile, um Details anzuzeigen. Im Spiel wählt ein Linksklick den Feind als Ziel, und ein Rechtsklick behält ihn als Ihren Fokus.",
  ["highground.coachtargeting.sample_rows_do_not_change_your_target.7affdd"] = "Beispielzeilen ändern Ihr Ziel oder Ihren Fokus nicht. Panel-Steuerelemente speichern Ihre tatsächlichen Einstellungen.",
  ["highground.coachtargeting.enable_enemy_list_in_game.ba1d59"] = "Feindesliste im Spiel aktivieren",
  ["highground.coachtargeting.read_the_recommendation_rank.0f34cd"] = "Lesen Sie den Empfehlungsrang",
  ["highground.coachtargeting.the_rank_suggests_who_to_attack_now.24df75"] = "Der Rang schlägt vor, wen man angreifen soll; JETZT markiert den erreichbaren Vorschlag. Zeilen verwenden Ihre aktuellen Darstellungs- und Sortiereinstellungen.",
  ["highground.coachtargeting.if_you_have_hidden_rank_numbers_in.6c1e0c"] = "Wenn Sie Rangnummern in der Darstellung von Schlachtfelder ausgeblendet haben, hebt die Anleitung stattdessen die Zeile hervor.",
  ["highground.coachtargeting.def_means_defense_active.f657f0"] = "DEF bedeutet Verteidigung aktiv",
  ["highground.coachtargeting.lunara_has_an_observed_defensive_ability_running.cef387"] = "Bei Lunara wurde eine aktive Verteidigungsfähigkeit beobachtet. Die echte Zeile zeigt DEF und dimmt ihren Inhalt ab.",
  ["highground.coachtargeting.status_labels_follow_your_battlegrounds_appearance_setting.ca7153"] = "Statusbeschriftungen folgen Ihren Darstellungseinstellungen von Schlachtfelder. Weiter zeigt das Ende dieser Verteidigung.",
  ["highground.coachtargeting.the_defense_has_ended.eab6dc"] = "Die Verteidigung ist beendet",
  ["highground.coachtargeting.lunara_s_defensive_ability_has_ended_spent.297484"] = "Lunaras Verteidigungsfähigkeit ist beendet. VERBRAUCHT markiert die jüngste Änderung; Sie entscheiden weiterhin, wann Sie angreifen.",
  ["highground.coachtargeting.spent_lasts_briefly_replay_shows_the_defense.870b3f"] = "VERBRAUCHT bleibt nur kurz sichtbar. Wiederholen zeigt das Ende der Verteidigung erneut.",
  ["highground.coachtargeting.immune_means_damage_is_blocked.f27940"] = "IMMUN bedeutet, dass Schaden blockiert wird",
  ["highground.coachtargeting.an_observed_immunity_prevents_damage_the_recommendation.2686ec"] = "Eine beobachtete Immunität verhindert Schäden. Die Empfehlung schließt diesen Feind bis zum Ende der Immunität aus.",
  ["highground.coachtargeting.cc_marks_breakable_crowd_control.5e7301"] = "CC markiert brechbare Crowd Control",
  ["highground.coachtargeting.attacking_this_enemy_may_break_the_effect.270e22"] = "Ein Angriff auf diesen Gegner kann den Effekt unterbrechen. Ihre Zielverhaltenseinstellungen entscheiden, ob diese Crowd-Kontrolle beibehalten werden soll.",
  ["highground.coachtargeting.unknown_distance_stays_unknown.01e741"] = "Unbekannte Entfernung bleibt unbekannt",
  ["highground.coachtargeting.the_distance_means_there_is_no_reliable.630799"] = "Die Entfernung -- bedeutet, dass es keine zuverlässige Reichweitenbeobachtung gibt. Sie bedeutet nicht null Meter, und dieser Feind kann keine erreichbare Empfehlung sein.",
  ["highground.coachtargeting.muted_health_is_the_last_reading.7d5664"] = "Gedämpfte Gesundheit ist der letzte Wert",
  ["highground.coachtargeting.lunara_left_your_view_so_her_bar.bbf3e8"] = "Lunara ist aus deinem Blickfeld verschwunden, daher sind ihre Leiste und ihr Prozentwert gedämpft: Sie zeigen ihre Gesundheit, als du sie zuletzt gesehen hast. Nach Zielverhalten > Zuletzt gesehene Gesundheit behalten wird die Leiste blass und unbekannt.",
  ["highground.coachtargeting.spectag.title"] = "Eine verborgene Spezialisierung markieren",
  ["highground.coachtargeting.spectag.text"] = "Wenn das Spiel die Spezialisierung eines Gegners nicht verrät, fahre mit der Maus über seine Zeile und klicke rechts auf eines der Spezialisierungssymbole. Mitspieler mit Highground sehen deine Markierung. Klicke erneut auf das markierte Symbol, um sie zu entfernen. Erkennt das Spiel die Spezialisierung später, ersetzt sie die Markierung.",
  ["highground.coachtargeting.spectag.hint"] = "Probiere es bei Lunara aus: Beispielmarkierungen bleiben in dieser Anleitung und werden nie geteilt.",
  ["highground.coachtools.find_your_saved_macros.a022e5"] = "Suchen Ihrer gespeicherten Makros",
  ["highground.coachtools.click_my_macros_to_see_the_macros.e3ce90"] = "Klicken Sie auf Meine Makros, um die bereits in WoW gespeicherten Makros anzuzeigen.",
  ["highground.coachtools.click_my_macros.6f7313"] = "Klicken Sie auf Meine Makros.",
  ["highground.coachtools.open_wow_s_macro_window.42985e"] = "Makrofenster von WoW öffnen",
  ["highground.coachtools.this_button_opens_the_game_s_own.386d0c"] = "Diese Schaltfläche öffnet das Makrofenster des Spiels. Ihre gespeicherten Makros werden dort ebenfalls angezeigt.",
  ["highground.coachtools.click_open_wow_macros_or_continue_to.2d0cfe"] = "Klicken Sie auf WoW-Makros öffnen oder fahren Sie fort, um den letzten Schritt zu lesen.",
