  ["highground.coachtools.read_the_preset_s_purpose_ready_to.84c1f3"] = "Lesen Sie den Zweck der Vorlage. Einsatzbereit bedeutet, dass ihre Zauber erlernt sind; Zauber nicht erlernt bedeutet, dass sie möglicherweise noch nicht funktioniert.",
  ["highground.coachtools.choose_who_receives_the_ability.4cec27"] = "Wählen Sie aus, wer die Fähigkeit erhält",
  ["highground.coachtools.open_the_target_menu_focus_keeps_a.cc40a3"] = "Öffnen Sie das Zielmenü. Fokus hält ein zweites Ziel; Mouseover verwendet die Einheit unter Ihrem Zeiger. Dadurch wird eine Version des Makros in der Vorschau angezeigt.",
  ["highground.coachtools.this_preset_has_a_fixed_target_there.01a659"] = "Diese Vorlage hat ein festes Ziel; es gibt kein Zielmenü.",
