  ["shared.previewsamples.sample_target.650520"] = "BEISPIELZIEL",
  ["shared.previewsamples.last_seen_value2.b31bec"] = "Zuletzt gesehen · {value2}",
  ["shared.previewsamples.value1_funds_reported_available_each_contribution_has.ea0853"] = "{value1} als verfügbar gemeldet · jeder Beitrag hat eigene Bedingungen",
  ["shared.previewsamples.5_reported_deaths_tarren_mill.b6b173"] = "5 gemeldete Tode · Tarrens Mühle",
  ["shared.previewsamples.nearby_alerts.429ece"] = "Nearby-Warnungen",
  ["shared.previewsamples.spot_a_wanted_player.3f246b"] = "Einen gesuchten Spieler finden",
  ["shared.previewsamples.see_the_wanted_popup_portrait_nearby_highlight.04e33a"] = "Sehen Sie sich das Steckbrief-Popup, das Porträt, die Nearby-Hervorhebung und die Münze am Namensschild an. „Wiederholen“ verwendet Ihre Soundeinstellungen.",
  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "Porträts verwenden Ihren ausgewählten Spieler oder Ihren Charakter als gekennzeichnetes Beispiel. Dabei wird nie ein Kopfgeld auf sie ausgesetzt. Live-Warnungen stammen aus Sichtungen, einschließlich Zielen, Mouseovern und Namensschildern.",
  ["shared.previewsamples.wanted_board.b69f07"] = "Steckbrieftafel",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "Steckbriefkarten und vollständige Steckbriefe",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "Klicken Sie auf die Steckbriefkarte oder auf Kopfgeld anzeigen, um jeden Beitragenden, seine Bedingungen, Finanzierung und Ablaufzeit zu prüfen. Aktualisieren zeigt eine deaktivierte Schaltfläche und eine Ladeanzeige, während Beispielbelohnungen eintreffen.",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "Verfolgung starten fügt ein Ziel zu Meine Kopfgelder hinzu. Nach einem erkannten Abschuss öffnet Bericht anzeigen dessen Status. Steckbriefe zeigen Ziel und Belohnung zuerst, nutzen die Pergamentbreite für Details und scrollen bei Bedarf. Nicht verfügbare Porträts sind gekennzeichnet.",
  ["shared.previewsamples.create_terms.1ea507"] = "Erstellen & Bedingungen",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "Beispiel-Kopfgeld erstellen",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "Drei Schritte: Ziel, Belohnung, Prüfen. Bis zur endgültigen Bestätigung wird nichts gespeichert. Standard ist ein Abschuss mit beliebigem Abschluss.",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "Speichern kehrt zur Tour zurück. Teilen ist optional. Privates Verfolgen kann null Gold verwenden; geteilte Belohnungen benötigen einen positiven Betrag und ein Ablaufdatum. Bevorzugte Finishes erfordern die Prüfung durch den Aussteller. Es wird keine echte Belohnung erstellt.",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "Gold über Ihre Charaktere hinweg nutzen",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "Sehen Sie sich eine Beispiel-Geldbörse und den Gold-Tooltip der Taschen an. Probieren Sie beide Schalter aus und geben Sie dann unter Erstellen & Bedingungen eine Belohnung ein, die größer ist als der verfügbare Betrag.",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "Die Account-Verfolgung ist standardmäßig aktiviert. Ausreichend Gold zu verlangen ist standardmäßig deaktiviert: Eine Belohnung über dem Budget erzeugt eine Warnung, kann aber erstellt werden. Guthaben gelten für diesen Realm oder die Forever-Realmgruppe. Guthaben von Twinks werden beim Einloggen aktualisiert; Zahlungen und Überweisungen bleiben manuell.",
  ["shared.previewsamples.guild_approval.d5172b"] = "Gildengenehmigung",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "Gilden-Kopfgeld einreichen und genehmigen",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "Probieren Sie ausstehende Genehmigung, Genehmigung durch Offiziere und Ablehnung aus und prüfen Sie dann die resultierende Steckbriefkarte. Diese Rollen sind in der Tour auch ohne Gilde verfügbar.",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "Genehmigte Gildenbelohnungen können einen Steckbrief NEUES KOPFGELD zeigen. Dieser kündigt eine Belohnung an, keine Sichtung. Eine Belohnung sowohl auf der Gilden- als auch auf der globalen Tafel zu teilen, erzeugt keine zweite Zahlungsverpflichtung. Auf Forever werden Community-Belohnungen nur mit Mitgliedern Ihres Regelwerks synchronisiert.",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "Geteilte Neuzugänge",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "Ein Kopfgeld entspricht Ihren Filtern",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "Verwenden Sie Verfolgung starten oder Ignorieren auf dem eingehenden Steckbrief. Testen Sie Beispiel-Warnungseinstellungen und Finanzierungsstatus. Dieses Ziel wurde noch nicht gesichtet.",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "Das Benachrichtigungsminimum zählt Belohnungen mit aktuellen Berichten über verfügbares Guthaben. Importierte, veraltete oder ungedeckte Angebote bleiben unterscheidbar. Verfolgen sagt kein Gold zu; Ignorieren schaltet die Kopfgeld- und Sichtungswarnungen des Ziels stumm.",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "Den Topf eines Kopfgelds vergrößern",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "Fügen Sie einen Beispielbeitrag hinzu, prüfen Sie die Bedingungen des ursprünglichen Ausstellers und sehen Sie, wie sich die Gesamtbelohnung aktualisiert.",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "Mit der Annahme der Bedingungen entscheidet der ursprüngliche Aussteller, ob ein Anspruch gültig ist. Beitragende schulden ihre Beträge demselben akzeptierten Kopfgeldjäger. Gold wird vom Addon weder verwahrt noch übertragen.",
  ["shared.previewsamples.share_import.d10b63"] = "Teilen & importieren",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "Kopfgeld-Link kopieren und Import prüfen",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "Das Teilen außerhalb des Addons ist optional. Kopieren Sie einen globalen, Gilden- oder privaten Kopfgeld-Link und sehen Sie sich dann einen Beispielimport an.",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "Wählen Sie Link zum Kopieren auswählen, drücken Sie Strg+C und senden Sie den Kopfgeld-Link. Der Empfänger wählt Kopfgeld importieren. Im Chat teilen ist für private und Gruppen-Kopfgelder verfügbar. Discord-Kanal öffnet das Ziel der gemeinsamen Tafel separat. Tour-Links sind außerhalb der Tour absichtlich ungültig.",
  ["shared.previewsamples.kills_reports.48e18a"] = "Kills & Berichte",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "Erkannte Kills erstellen automatisch Berichte",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "Verwenden Sie Beispielbericht anzeigen, um die Prüfung zu verfolgen. Probieren Sie wiederholte Kills sowie Screenshot-Erfolg, -Fehler oder -Wiederholung aus. Das Kopieren des Nachweises ist optional.",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "Lesbare Todesstöße werden lokal bestätigt. Namentliche Ehrengutschriften können Unterstützungen enthalten. Ein Screenshot-Häkchen bestätigt nur, dass das Bild gespeichert wurde. Belohnungsgenehmigung und Zahlung bleiben getrennt; manuelles Melden ist für verpasste Erkennungen gedacht. Diese Tour erstellt keine Screenshots.",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "Berichte durch Überprüfung und Zahlung verfolgen",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "Durchsuchen Sie Beispiele für Kopfgeldjäger und Aussteller: ausstehende Prüfung, genehmigt, bezahlt und abgelehnt. Probieren Sie als Beispiel-Aussteller Genehmigen, Ablehnen und Als bezahlt markieren aus.",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "Kopfgeldjäger können ihre eigenen Berichte nicht genehmigen. Der Aussteller prüft die Nachweise, zahlt manuell im Spiel und erfasst dann diese Zahlung. Wiederholte Kills können auf ein Mehrfach-Kill-Ziel angerechnet werden, ohne dieselbe Belohnung zweimal zu zahlen.",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "Von Todesberichten vorgeschlagene Gegner prüfen",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "Prüfen Sie Beispielberichte, überprüfen Sie ein vorgefülltes Kopfgeld, verwerfen Sie den Vorschlag oder ignorieren Sie den Feind.",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "Vorschläge kombinieren Ihre Tode und die Berichte teilnehmender Gildenmitglieder innerhalb des konfigurierten Zeitfensters. Sie sind Hinweise zur Prüfung, kein vom Server bestätigter Abschussnachweis. Nichts wird ausgesetzt, bis Sie eine Sichtbarkeit wählen und speichern.",
  ["shared.previewtest.leave_combat_before_starting_a_bounty_preview.0cf3f1"] = "Verlassen Sie den Kampf, bevor Sie eine Kopfgeld-Vorschau starten.",
  ["shared.previewview.nearby_row.e41e3b"] = "NEARBY-ZEILE",
  ["shared.previewview.85_tarren_mill_now.70f627"] = "85 · Tarrens Mühle · jetzt",
