  ["alerts.guide.level"] = "Eine Vorlage setzt die Text- und Tonschalter aller Warnungen auf einmal. „Nur Text“ behält schriftliche Warnungen und schaltet jeden Ton aus.",
  ["alerts.guide.channels_bg"] = "Diese Schalter gehören zu den Einstellungen von Schlachtfelder; Nearby und Kopfgelder haben eigene. Jeder Schalter entscheidet allein. Der Schalter „Klänge“ in den Gemeinsamen Voreinstellungen schaltet jeden Ton stumm.",
  ["alerts.guide.channels_shared"] = "Gegnerische Verstohlenheit gilt für alle Addons; andere Warnungen liegen in den Einstellungen ihres Addons. Jeder Schalter entscheidet allein. Der Schalter „Klänge“ in den Gemeinsamen Voreinstellungen schaltet jeden Ton stumm.",
  ["nearby.sound.tooltip"] = "Schaltet Töne für neue Feinde ein oder aus: der Tonschalter „Feind in der Nähe“ in den Warnungseinstellungen von Nearby. Gegnerische Verstohlenheit hat einen eigenen Schalter. Stummgeschaltete Feinde bleiben still.",
  ["nearby.world.map_label"] = "Sichtungen auf der Weltkarte",
